package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.view.inspector.WindowInspector;
import android.graphics.Rect;
import android.widget.TextView;
import java.io.PrintWriter;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Private config only. Permission action is injected; a real sensor port must never be constructed. */
public class WalkConfigurationFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private String step="fixture admission";
    private void await(java.util.function.BooleanSupplier ready){assertTrue(step,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return ready.getAsBoolean();}},5000));}
    private View find(View root,String value,boolean description){if(description?value.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()):root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),value,description);if(view!=null)return view;}return null;}
    private View focusedWindow(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0){assertNull("One focused application window",found);found=root;}return found;}
    private void ready(){await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&focusedWindow()==activity.getWindow().getDecorView());return yes[0];});}
    private void frame(View owner)throws Exception{CountDownLatch drawn=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Exact focused window before frame",owner,focusedWindow());owner.getViewTreeObserver().registerFrameCommitCallback(drawn::countDown);owner.invalidate();});assertTrue(step+": rendered owned frame",drawn.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame("Frame retains its exact focused window",owner,focusedWindow()));}
    private void require(String value,boolean description){step="require page "+value;ready();await(()->{boolean[] yes={false};i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),value,description);if(target==null)return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();yes[0]=target.isShown()&&target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return yes[0];});}
    private boolean hasText(String text){boolean[] found={false};i.runOnMainSync(()->found[0]=find(activity.getWindow().getDecorView(),text,false)!=null);return found[0];}
    private void input(View owner,String value,boolean description)throws Exception{
        step="single owned input "+value;
        await(()->{boolean[] ready={false};i.runOnMainSync(()->{if(focusedWindow()!=owner)return;View target=find(owner,value,description);if(target==null)return;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();if(!target.isClickable()||!target.isEnabled())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();ready[0]=target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return ready[0];});
        frame(owner);Rect screen=new Rect();i.runOnMainSync(()->{assertSame(owner,focusedWindow());View target=find(owner,value,description);assertNotNull(step,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertSame("Control belongs to exact decor",owner,target.getRootView());assertTrue(target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals("Complete control width",target.getWidth(),visible.width());assertEquals("Complete control height",target.getHeight(),visible.height());assertTrue("48dp width",visible.width()>=Design.dp(c,48));assertTrue("48dp height",visible.height()>=Design.dp(c,48));int[] position=new int[2];target.getLocationOnScreen(position);screen.set(position[0],position[1],position[0]+target.getWidth(),position[1]+target.getHeight());});
        // Exactly one input. Never repeat a delivered action after an absent postcondition.
        assertTrue(step+": dispatched once",device.click(screen.centerX(),screen.centerY()));
    }
    private void click(String text)throws Exception{ready();input(activity.getWindow().getDecorView(),text,false);}
    private void clickDescription(String value)throws Exception{ready();input(activity.getWindow().getDecorView(),value,true);}
    private View targetDialog()throws Exception{step="await actual Target steps selector";View[] owner={null};await(()->{i.runOnMainSync(()->{View root=focusedWindow();if(root!=null&&root!=activity.getWindow().getDecorView()&&find(root,"Target steps",false)!=null&&find(root,"Options for Target steps",true)!=null)owner[0]=root;});return owner[0]!=null;});frame(owner[0]);return owner[0];}
    private void choose(View owner,String value,boolean description)throws Exception{input(owner,value,description);step="await exact selector detachment after "+value;await(()->!owner.isAttachedToWindow());ready();frame(activity.getWindow().getDecorView());}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Edit alarm",false);}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Use Walk",false);}
    private void capture(String name)throws Exception{step="capture walk-"+name;ready();frame(activity.getWindow().getDecorView());File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"walk-"+name+".png")));}
    @Test public void targetAndPermissionStatesPersistWithoutSensorsOrPermissionDialogs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));String name="walk-"+UUID.randomUUID()+".db";Records.Factory oldRecords=Records.factory;AlarmScheduling.Port oldSchedule=AlarmScheduling.port;WalkPermission.Port oldAccess=WalkPermission.port;WalkPlatform.Factory oldSensors=WalkPlatform.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());WalkPermission.Status[] status={WalkPermission.Status.NEEDED};boolean[] fail={false};int[] requests={0},scheduled={0};List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue(a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse(alarm.enabled);scheduled[0]++;}};WalkPlatform.factory=context->{throw new AssertionError("Configuration cannot construct a sensor listener");};WalkPermission.port=new WalkPermission.Port(){public WalkPermission.Status status(Activity a){return status[0];}public void request(Activity a){requests[0]++;if(fail[0])throw new IllegalStateException("Fixture request error");status[0]=WalkPermission.Status.READY;}};});
            Alarm initial=new Alarm(1);Alarm preserved=new Alarm(2);preserved.label="Preserved alarm";String untouched=preserved.json().toString();try(Store store=new Store(c,name)){store.save(initial);store.save(preserved);}launch(initial);click("Challenges");clickDescription("Configure Walk");require("Use Walk",false);
            clickDescription("Target steps");View selected=targetDialog();choose(selected,"20 steps",true);require("20 steps",false);
            clickDescription("Target steps");View cancelled=targetDialog();assertNotSame("Reopened selector has a fresh owner",selected,cancelled);i.runOnMainSync(()->assertTrue("The saved draft choice is selected in the new selector",find(cancelled,"20 steps",true).isSelected()));choose(cancelled,"Cancel",false);
            require("20 steps",false);require("Math replaces unavailable steps. You can also choose it while walking.",false);capture("permission");click("Allow physical activity");require("Allowed",false);assertEquals(1,requests[0]);capture("ready");
            status[0]=WalkPermission.Status.SETTINGS;recreate();require("Open activity settings",false);require("20 steps",false);capture("settings");fail[0]=true;click("Open activity settings");require("Physical activity access could not be opened. Try again.",false);capture("error");assertEquals(2,requests[0]);status[0]=WalkPermission.Status.UNSUPPORTED;recreate();require("This phone has no supported step sensor.",false);assertFalse("A previous request error must not describe the new unavailable state",hasText("Physical activity access could not be opened. Try again."));capture("unavailable");click("Use Walk");require("Edit task 2 Walk",true);click("Save routine");try(Store store=new Store(c,name)){assertFalse(store.alarm(1).json().has("routine"));}click("Save alarm");long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());
            Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);assertEquals(untouched,store.alarm(2).json().toString());assertEquals(20,saved.challenges().tasks.get(1).targetSteps);assertEquals("Walk",saved.challenges().tasks.get(1).type);assertEquals(1,saved.challenges().tasks.get(1).units());Backup.validate(store.backup());JSONObject bad=saved.json();bad.getJSONArray("routine").getJSONObject(1).put("steps",20.5);assertTrue(Alarm.read(bad).routineInvalid);}
            assertEquals(1,scheduled[0]);status[0]=WalkPermission.Status.READY;fail[0]=false;launch(saved);click("Challenges");clickDescription("Edit task 2 Walk");require("20 steps",false);require("Math replaces unavailable steps. You can also choose it while walking.",false);capture("reopened");assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());try(PrintWriter out=new PrintWriter(new File(folder,"walk-failure.txt"),"UTF-8")){out.println("Last action/await: "+step);out.println("Permission fixture: "+status[0]+"; requests="+requests[0]+"; schedules="+scheduled[0]);failure.printStackTrace(out);}device.takeScreenshot(new File(folder,"walk-failure.png"));device.dumpWindowHierarchy(new File(folder,"walk-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{Records.factory=oldRecords;AlarmScheduling.port=oldSchedule;WalkPermission.port=oldAccess;WalkPlatform.factory=oldSensors;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);}}
    }
}
